import com.conversational.commerce.core.engine.model.Blocks.Comparison;
import com.conversational.commerce.core.engine.provider.ModelRequest;
import com.conversational.commerce.core.engine.provider.ModelResult;
import com.conversational.commerce.core.engine.provider.ModelRouter;
import com.conversational.commerce.core.engine.provider.ModelTask;
import com.conversational.commerce.core.engine.sanitiser.SanitisedPayload;
import com.conversational.commerce.core.engine.sanitiser.Sanitiser;
import jakarta.annotation.Resource;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * COMPOSE/EXPLAIN task plus validate-then-reveal (A13): slots only, no loose digits, no unknown product codes, text agrees
 * with the table. Any failure swaps in the fixed template text, so a bad model answer never reaches the dealer.
 */
public class Composer
{
    private static final Pattern CODE = Pattern.compile("\\b[A-Z]{2,4}-\\d{3,6}\\b");

    @Resource(name = "ccSanitiser")
    private Sanitiser sanitiser;

    @Resource(name = "ccModelRouter")
    private ModelRouter modelRouter;

    @Resource(name = "ccPromptRepository")
    private PromptRepository promptRepository;

    @Resource(name = "ccAuditSink")
    private AuditSink auditSink;

    private final TextTableChecker tableChecker = new TextTableChecker();

    public void setSanitiser(final Sanitiser s)
    {
        this.sanitiser = s;
    }

    public void setModelRouter(final ModelRouter r)
    {
        this.modelRouter = r;
    }

    public void setPromptRepository(final PromptRepository p)
    {
        this.promptRepository = p;
    }

    public void setAuditSink(final AuditSink a)
    {
        this.auditSink = a;
    }

    /** @param facts text-only facts for the model; amounts are not in here, only slot names are sent. */
    public String compose(final TurnState state, final String templateKey, final Map<String, Object> facts,
            final Map<String, String> slots, final Comparison table)
    {
        final String template = SlotFiller.fill(TemplateTexts.get(templateKey), slots);
        final String fallback = template == null ? TemplateTexts.get(templateKey) : template;
        try
        {
            final ModelTask task = table == null ? ModelTask.COMPOSE : ModelTask.EXPLAIN;
            final String promptId = table == null ? "compose.v1" : "explain.v1";
            final Map<String, Object> fields = new LinkedHashMap<>();
            fields.put("intent", templateKey);
            final Map<String, Object> allFacts = new LinkedHashMap<>(facts);
            if (table != null)
            {
                fields.put("comparison", tableAsMap(table));
            }
            fields.put("facts", allFacts);
            fields.put("slots", new ArrayList<>(slots.keySet()));
            fields.put("language", "en");
            final SanitisedPayload payload = sanitiser.sanitise(task, fields, state.tokens, state.secrets);
            final ModelResult result = modelRouter.call(new ModelRequest(task, promptId, promptRepository.prompt(promptId),
                    payload, promptRepository.schema("compose.v1"), 400, 0.2));
            state.addUsage(result.tokensIn(), result.tokensOut());
            final String modelText = result.json().path("text").asText("");
            return validate(state, modelText, slots, facts, table) ? SlotFiller.fill(modelText, slots) : fallback;
        }
        catch (final RuntimeException e)
        {
            auditSink.log(AuditEvent.of("compose_fallback").with("responseId", state.responseId).with("errorCode",
                    e.getClass().getSimpleName()));
            return fallback;
        }
    }

    private boolean validate(final TurnState state, final String text, final Map<String, String> slots,
            final Map<String, Object> facts, final Comparison table)
    {
        if (text.isBlank() || SlotFiller.fill(text, slots) == null)
        {
            return reject(state, "bad_slot");
        }
        final List<String> allowedLiterals = new ArrayList<>();
        facts.values().forEach(v -> allowedLiterals.add(String.valueOf(v)));
        if (table != null)
        {
            table.rows().forEach(r -> allowedLiterals.addAll(r.values()));
        }
        if (SlotFiller.hasLooseDigits(text, allowedLiterals))
        {
            return reject(state, "loose_digits");
        }
        final Matcher m = CODE.matcher(text);
        while (m.find())
        {
            if (!state.provenance.contains(m.group()))
            {
                return reject(state, "unknown_code");
            }
        }
        if (table != null && !tableChecker.consistent(SlotFiller.fill(text, slots), table))
        {
            return reject(state, "text_table_mismatch");
        }
        return true;
    }

    private boolean reject(final TurnState state, final String reason)
    {
        auditSink.log(AuditEvent.of("text_rejected").with("responseId", state.responseId).with("errorCode", reason));
        return false;
    }

    private Map<String, Object> tableAsMap(final Comparison table)
    {
        final Map<String, Object> map = new LinkedHashMap<>();
        map.put("columns", table.columns());
        final List<Map<String, Object>> rows = new ArrayList<>();
        table.rows().forEach(r -> rows.add(Map.of("attribute", r.attributeLabel(), "values", r.values())));
        map.put("rows", rows);
        map.put("notes", table.notes());
        return map;
    }
}

package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import com.fasterxml.jackson.databind.JsonNode;
import jakarta.annotation.Resource;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/** Validates the DECIDE output against the catalogue of intents, enabled capabilities and numeric ranges. */
public class DecisionValidator
{
    private static final Set<String> EVENTS = Set.of("VIEWED", "COMPARED", "SHORTLISTED", "REQUESTED_NOT_FOUND");
    private static final Set<String> STATUSES = Set.of("ALL", "UNDELIVERED", "PENDING", "DELIVERED");
    private static final Set<String> PERIODS = Set.of("NONE", "LAST_MONTH", "LAST_30_DAYS", "THIS_MONTH");
    private static final Pattern CODE = Pattern.compile("[A-Z]{2,4}-\\d{3,6}");
    private static final double MAX_AMOUNT = 10_000_000_000.0;

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;

    @Resource(name = "ccAuditSink")
    private AuditSink auditSink;

    public void setConfigurationService(final CcConfigurationService c)
    {
        this.configurationService = c;
    }

    public void setAuditSink(final AuditSink a)
    {
        this.auditSink = a;
    }

    public Decision validate(final TurnState state, final JsonNode json)
    {
        Intent intent;
        try
        {
            intent = Intent.valueOf(json.path("intent").asText("CLARIFY"));
        }
        catch (final IllegalArgumentException e)
        {
            audit(state, "unknown_intent");
            intent = Intent.CLARIFY;
        }
        final double confidence = Math.max(0, Math.min(1, json.path("confidence").asDouble(0)));
        if (confidence < configurationService.getInt("decision.minConfidencePercent", 40) / 100.0 && intent != Intent.OFF_TOPIC)
        {
            intent = Intent.CLARIFY;
        }
        final Set<String> allowedFilterKeys = new java.util.HashSet<>(Arrays.asList(
                configurationService.getString("pack." + state.pack + ".searchFields", "").split(",")));
        final Map<String, String> filters = new LinkedHashMap<>();
        for (final JsonNode f : json.path("filters"))
        {
            final String key = f.path("key").asText();
            if (allowedFilterKeys.contains(key) && filters.size() < 8)
            {
                filters.put(key, trim(f.path("value").asText(), 60));
            }
            else
            {
                audit(state, "filter_key_rejected");
            }
        }
        final List<String> codes = new ArrayList<>();
        for (final JsonNode c : json.path("codes"))
        {
            if (CODE.matcher(c.asText()).matches() && codes.size() < 10)
            {
                codes.add(c.asText());
            }
        }
        final String status = STATUSES.contains(json.path("orderStatus").asText()) ? json.path("orderStatus").asText() : "ALL";
        final String period = PERIODS.contains(json.path("orderPeriod").asText()) ? json.path("orderPeriod").asText() : "NONE";
        final String event = json.path("eventSuggestion").asText("NONE");
        return new Decision(intent, confidence, trim(json.path("language").asText("en"), 8), strings(json.path("keywords"), 12, 40),
                trim(json.path("categoryHint").asText(""), 60), filters, amount(json.path("budgetAmount")),
                amount(json.path("maxUnitAmount")), codes, status, amount(json.path("orderMinAmount")), period,
                json.path("wantsLatestTracking").asBoolean(false), EVENTS.contains(event) ? event : "NONE",
                trim(json.path("clarifyKey").asText(""), 60));
    }

    private Double amount(final JsonNode node)
    {
        if (!node.isNumber() || node.asDouble() <= 0 || node.asDouble() > MAX_AMOUNT)
        {
            return null;
        }
        return node.asDouble();
    }

    private List<String> strings(final JsonNode array, final int max, final int maxLen)
    {
        final List<String> list = new ArrayList<>();
        for (final JsonNode n : array)
        {
            if (list.size() < max && !n.asText().isBlank())
            {
                list.add(trim(n.asText(), maxLen));
            }
        }
        return list;
    }

    private String trim(final String value, final int max)
    {
        return value.length() > max ? value.substring(0, max) : value;
    }

    private void audit(final TurnState state, final String code)
    {
        auditSink.log(AuditEvent.of("decision_adjusted").with("responseId", state.responseId).with("errorCode", code));
    }
}

package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.ChatEvent;
import com.conversational.commerce.core.engine.model.ChatEventListener;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.model.TurnRequest;
import com.conversational.commerce.core.engine.model.TurnResult;
import com.conversational.commerce.core.engine.provider.ModelRequest;
import com.conversational.commerce.core.engine.provider.ModelResult;
import com.conversational.commerce.core.engine.provider.ModelRouter;
import com.conversational.commerce.core.engine.provider.ModelTask;
import com.conversational.commerce.core.engine.sanitiser.DefaultSanitiser.SanitiserDisabledException;
import com.conversational.commerce.core.engine.sanitiser.OutboundGuard.EgressBlockedException;
import com.conversational.commerce.core.engine.sanitiser.SanitisedPayload;
import com.conversational.commerce.core.engine.sanitiser.Sanitiser;
import jakarta.annotation.Resource;
import java.time.Clock;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.regex.Pattern;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class DefaultChatOrchestrationService implements ChatOrchestrationService
{
    private static final Logger LOG = LogManager.getLogger(DefaultChatOrchestrationService.class);
    private static final Pattern CODE = Pattern.compile("[A-Z]{2,4}-\\d{3,6}");
    private static final int CHUNK_WORDS = 3;
    private static final java.util.Set<String> UNRESOLVED = java.util.Set.of("find_none", "faq_none", "qa_none", "order_none",
            "reorder_none", "next_order_none", "unsupported");

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;
    @Resource(name = "ccSanitiser")
    private Sanitiser sanitiser;
    @Resource(name = "ccModelRouter")
    private ModelRouter modelRouter;
    @Resource(name = "ccPromptRepository")
    private PromptRepository promptRepository;
    @Resource(name = "ccDecisionValidator")
    private DecisionValidator decisionValidator;
    @Resource(name = "ccWorkflowRegistry")
    private WorkflowRegistry workflowRegistry;
    @Resource(name = "ccComposer")
    private Composer composer;
    @Resource(name = "ccTranslateStep")
    private TranslateStep translateStep;
    @Resource(name = "ccUsageCapService")
    private UsageCapService usageCapService;
    @Resource(name = "ccInterestEventService")
    private InterestEventService interestEventService;
    @Resource(name = "ccAuditSink")
    private AuditSink auditSink;

    private final LanguageDetector languageDetector = new LanguageDetector();
    private Clock clock = Clock.systemDefaultZone();

    public void setConfigurationService(final CcConfigurationService v)
    {
        this.configurationService = v;
    }

    public void setSanitiser(final Sanitiser v)
    {
        this.sanitiser = v;
    }

    public void setModelRouter(final ModelRouter v)
    {
        this.modelRouter = v;
    }

    public void setPromptRepository(final PromptRepository v)
    {
        this.promptRepository = v;
    }

    public void setDecisionValidator(final DecisionValidator v)
    {
        this.decisionValidator = v;
    }

    public void setWorkflowRegistry(final WorkflowRegistry v)
    {
        this.workflowRegistry = v;
    }

    public void setComposer(final Composer v)
    {
        this.composer = v;
    }

    public void setTranslateStep(final TranslateStep v)
    {
        this.translateStep = v;
    }

    public void setUsageCapService(final UsageCapService v)
    {
        this.usageCapService = v;
    }

    public void setInterestEventService(final InterestEventService v)
    {
        this.interestEventService = v;
    }

    public void setAuditSink(final AuditSink v)
    {
        this.auditSink = v;
    }

    public void setClock(final Clock clock)
    {
        this.clock = clock;
    }

    @Override
    public TurnResult handle(final TurnRequest request, final ChatEventListener listener)
    {
        final LocalDate today = LocalDate.now(clock);
        final TurnState state = new TurnState(request, configurationService.activePack(), today, UUID.randomUUID().toString(),
                listener, configurationService.getInt("orchestration.maxSteps", 8),
                configurationService.getInt("orchestration.maxSeconds", 9));
        final long start = System.currentTimeMillis();
        Intent intent = Intent.CLARIFY;
        final List<Block> blocks = new ArrayList<>();
        final List<String> actions = new ArrayList<>();
        try
        {
            if (!configurationService.isEnabled("PL-04"))
            {
                return finish(state, intent, notice(blocks, "unavailable", "unavailableNotice"), actions, start);
            }
            if (!usageCapService.checkAndIncrement(state.customerId, today))
            {
                return finish(state, intent, notice(blocks, "cap_reached", "usageCap"), actions, start);
            }
            state.language = languageDetector.detect(request.message(), request.uiLocale());
            if (!"en".equals(state.language) && configurationService.isEnabled("CF-05"))
            {
                final Optional<String> english = state.step("step.translating",
                        () -> translateStep.translate(state, request.message(), state.language, "en"));
                if (english.isEmpty())
                {
                    state.language = "en";
                    return finish(state, intent, notice(blocks, "clarify", "translationFailed"), actions, start);
                }
                state.workingMessage = english.get();
            }
            final Decision decision = state.step("step.understanding", () -> decide(state));
            intent = decision.intent();
            if (intent.capabilityId() != null && !configurationService.isEnabled(intent.capabilityId()))
            {
                intent = Intent.UNSUPPORTED;
            }
            final WorkflowTemplate workflow = workflowRegistry.find(intent).orElse(workflowRegistry.find(Intent.CLARIFY).orElseThrow());
            final WorkflowTemplate.Output output = workflow.run(state, decision);
            blocks.addAll(output.blocks());
            actions.addAll(output.suggestedActions());
            interestEventService.maybeRecord(state, decision);
            String text = output.templateKey() == null ? null : textFor(state, output);
            if (text != null && UNRESOLVED.contains(output.templateKey()))
            {
                text = text + " " + configurationService.getString("contact.text", TemplateTexts.get("contact")); // D31
            }
            if (output.templateKey() == null)
            {
                // approved FAQ text is already in the blocks
                return finish(state, intent, blocks, actions, start);
            }
            blocks.add(Block.text("b-text", text));
            return finish(state, intent, translateOut(state, blocks), actions, start);
        }
        catch (final LimitExceededException e)
        {
            audit(state, "limit_exceeded", e.getMessage());
            notice(blocks, "partial", "partialNotice");
            return finish(state, intent, blocks, actions, start);
        }
        catch (final ToolRejectedException e)
        {
            audit(state, "tool_rejected", e.getMessage());
            blocks.clear();
            notice(blocks, "clarify", "toolRejected");
            return finish(state, intent, blocks, actions, start);
        }
        catch (final SanitiserDisabledException | EgressBlockedException | ModelRouter.ModelUnavailableException e)
        {
            audit(state, "model_blocked", e.getClass().getSimpleName());
            blocks.clear();
            notice(blocks, "unavailable", "unavailableNotice");
            blocks.add(Block.text("b-contact", configurationService.getString("contact.text", TemplateTexts.get("contact"))));
            return finish(state, intent, blocks, actions, start);
        }
    }

    private String textFor(final TurnState state, final WorkflowTemplate.Output output)
    {
        if (output.facts().isEmpty() && output.slots().isEmpty())
        {
            final String filled = SlotFiller.fill(TemplateTexts.get(output.templateKey()), output.slots());
            return filled == null ? TemplateTexts.get(output.templateKey()) : filled;
        }
        return state.step("step.writingReply", () -> composer.compose(state, output.templateKey(), output.facts(), output.slots(),
                output.table()));
    }

    private List<Block> notice(final List<Block> blocks, final String templateKey, final String noticeKey)
    {
        blocks.add(Block.notice("b-notice", noticeKey, TemplateTexts.get(templateKey)));
        return blocks;
    }

    private Decision decide(final TurnState state)
    {
        final Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("message", state.workingMessage);
        final List<String> intents = new ArrayList<>();
        for (final Intent i : Intent.values())
        {
            if (i.capabilityId() == null || configurationService.isEnabled(i.capabilityId()))
            {
                intents.add(i.name());
            }
        }
        fields.put("capabilities", intents);
        fields.put("terminology", configurationService.getString("pack." + state.pack + ".terminology", ""));
        fields.put("turns", boundedTurns(state.request));
        fields.put("shortlistCodes", state.request.shortlistCodes().stream().filter(c -> CODE.matcher(c).matches()).limit(10).toList());
        fields.put("language", "en");
        final SanitisedPayload payload = sanitiser.sanitise(ModelTask.DECIDE, fields, state.tokens, state.secrets);
        final ModelResult result = modelRouter.call(new ModelRequest(ModelTask.DECIDE, "decide.v1",
                promptRepository.prompt("decide.v1"), payload, promptRepository.schema("decision.v1"), 500, 0.0));
        state.addUsage(result.tokensIn(), result.tokensOut());
        auditSink.log(AuditEvent.of("model_call").with("responseId", state.responseId).with("stepName", "DECIDE")
                .with("provider", result.provider()).with("model", result.model()).with("promptVersion", "decide.v1")
                .with("tokensIn", result.tokensIn()).with("tokensOut", result.tokensOut()).with("latencyMs", result.latencyMs()));
        return decisionValidator.validate(state, result.json());
    }

    /** Browser-held context is untrusted (A11): bounded here and re-masked by the sanitiser on every call. */
    private List<Map<String, String>> boundedTurns(final TurnRequest request)
    {
        final int maxTurns = configurationService.getInt("context.maxTurns", 6);
        int budget = configurationService.getInt("context.maxChars", 2000);
        final List<Map<String, String>> out = new ArrayList<>();
        final List<TurnRequest.ContextTurn> turns = request.turns();
        for (int i = turns.size() - 1; i >= 0 && out.size() < maxTurns; i--)
        {
            final TurnRequest.ContextTurn t = turns.get(i);
            final String role = "assistant".equals(t.role()) ? "assistant" : "user";
            final String text = t.text() == null ? "" : t.text();
            if (text.length() > budget)
            {
                break;
            }
            budget -= text.length();
            out.add(0, Map.of("role", role, "text", text));
        }
        return out;
    }

    private List<Block> translateOut(final TurnState state, final List<Block> blocks)
    {
        if ("en".equals(state.language) || !configurationService.isEnabled("CF-05"))
        {
            return blocks;
        }
        final List<Block> result = new ArrayList<>();
        for (final Block block : blocks)
        {
            if ("text".equals(block.type()) && block.text() != null)
            {
                final Optional<String> translated = state.step("step.translating",
                        () -> translateStep.translate(state, block.text(), "en", state.language));
                if (translated.isPresent())
                {
                    result.add(block.withText(translated.get()));
                }
                else
                {
                    result.add(block);
                    result.add(Block.notice("b-translation", "translationFailed", TemplateTexts.get("translation_failed")));
                }
            }
            else
            {
                result.add(block);
            }
        }
        return result;
    }

    private TurnResult finish(final TurnState state, final Intent intent, final List<Block> blocks, final List<String> actions,
            final long start)
    {
        for (final Block block : blocks)
        {
            if ("text".equals(block.type()) && block.text() != null)
            {
                state.listener.onEvent(ChatEvent.block(block.withText("")));
                streamText(state, block);
            }
            else
            {
                state.listener.onEvent(ChatEvent.block(block));
            }
        }
        state.listener.onEvent(ChatEvent.done(state.responseId, List.copyOf(state.trace)));
        usageCapService.recordTokens(state.customerId, state.today, state.tokensIn.get() + state.tokensOut.get());
        auditSink.log(AuditEvent.of("turn_completed").with("responseId", state.responseId).with("intent", intent.name())
                .with("workflow", intent.name()).with("tokensIn", state.tokensIn.get()).with("tokensOut", state.tokensOut.get())
                .with("latencyMs", System.currentTimeMillis() - start).with("outcome", "ok"));
        LOG.debug("Turn {} finished with intent {}", state.responseId, intent);
        return new TurnResult(state.responseId, state.language, intent, List.copyOf(blocks), List.copyOf(actions),
                List.copyOf(state.trace), state.tokensIn.get(), state.tokensOut.get());
    }

    private void streamText(final TurnState state, final Block block)
    {
        final String[] words = block.text().split("(?<=\\s)");
        final StringBuilder chunk = new StringBuilder();
        int n = 0;
        for (final String w : words)
        {
            chunk.append(w);
            if (++n % CHUNK_WORDS == 0)
            {
                state.listener.onEvent(ChatEvent.textDelta(block.blockId(), chunk.toString()));
                chunk.setLength(0);
            }
        }
        if (chunk.length() > 0)
        {
            state.listener.onEvent(ChatEvent.textDelta(block.blockId(), chunk.toString()));
        }
    }

    private void audit(final TurnState state, final String event, final String code)
    {
        auditSink.log(AuditEvent.of(event).with("responseId", state.responseId).with("errorCode", code));
    }
}

package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.gateway.CatalogGateway;
import com.conversational.commerce.core.engine.gateway.PriceGateway;
import com.conversational.commerce.core.engine.gateway.StockGateway;
import com.conversational.commerce.core.engine.model.Blocks.ListLine;
import com.conversational.commerce.core.engine.model.Blocks.OrderSummary;
import com.conversational.commerce.core.engine.model.Blocks.ProductCard;
import com.conversational.commerce.core.engine.model.Blocks.Recommendation;
import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Domain.Product;
import com.conversational.commerce.core.engine.model.Domain.StockInfo;
import jakarta.annotation.Resource;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;

/** Adds names, customer prices, images and labelled demo stock after the model is done (D26). Prices never go to a model. */
public class Hydrator
{
    @Resource(name = "ccCatalogGateway")
    private CatalogGateway catalogGateway;

    @Resource(name = "ccPriceGateway")
    private PriceGateway priceGateway;

    @Resource(name = "ccStockGateway")
    private StockGateway stockGateway;

    public void setCatalogGateway(final CatalogGateway g)
    {
        this.catalogGateway = g;
    }

    public void setPriceGateway(final PriceGateway g)
    {
        this.priceGateway = g;
    }

    public void setStockGateway(final StockGateway g)
    {
        this.stockGateway = g;
    }

    public String name(final TurnState state, final String code)
    {
        return catalogGateway.byCode(state.pack, code).map(Product::name).orElse(code);
    }

    public ProductCard card(final TurnState state, final String code, final Map<String, String> reasonSlots)
    {
        final Optional<Product> product = catalogGateway.byCode(state.pack, code);
        final String price = priceText(state, code);
        final StockInfo stock = stockGateway.stockOf(code);
        return new ProductCard(code, product.map(Product::name).orElse(code), price, stock.label(), stock.demo(), reasonSlots);
    }

    public ListLine line(final TurnState state, final String code, final int quantity, final String origin, final String issue)
    {
        final OptionalLong unit = priceGateway.unitPriceMinor(state.customerId, code);
        String lineText = null;
        if (unit.isPresent())
        {
            final long total = unit.getAsLong() * quantity;
            lineText = MoneyFormat.format(total, priceGateway.currency());
            markSecret(state, total);
        }
        return new ListLine(code, name(state, code), quantity, null, origin, lineText, issue);
    }

    public Recommendation recommendation(final TurnState state, final String code, final int quantity, final String reasonKey,
            final boolean estimate)
    {
        return new Recommendation(code, name(state, code), quantity, reasonKey, estimate);
    }

    public OrderSummary order(final Order order)
    {
        return new OrderSummary(order.code(), order.placedOn().toString(), order.status().name(),
                MoneyFormat.format(order.totalMinor(), order.currency()), order.trackingReference(), "Commerce order data");
    }

    public String format(final TurnState state, final long minor)
    {
        markSecret(state, minor);
        return MoneyFormat.format(minor, priceGateway.currency());
    }

    private String priceText(final TurnState state, final String code)
    {
        final OptionalLong unit = priceGateway.unitPriceMinor(state.customerId, code);
        if (unit.isEmpty())
        {
            return null;
        }
        markSecret(state, unit.getAsLong());
        return MoneyFormat.format(unit.getAsLong(), priceGateway.currency());
    }

    /** Registers every textual form of an amount so the outbound guard can block it. */
    public void markSecret(final TurnState state, final long minor)
    {
        state.secrets.add(String.valueOf(minor));
        state.secrets.add(String.format("%d.%02d", minor / 100, Math.abs(minor % 100)));
        state.secrets.add(String.format(java.util.Locale.ROOT, "%,d.%02d", minor / 100, Math.abs(minor % 100)));
    }
}

package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.gateway.InterestEventSink;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.EventType;
import jakarta.annotation.Resource;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * The only writer of interest events (CI-04, D08, A9). The model suggests an enum; the backend decides, and stores only the
 * enum, a code or a normalised token. No text. Writes nothing when privacy.interestEvents.enabled is false.
 */
public class InterestEventService
{
    private static final Pattern TOKEN_OK = Pattern.compile("[a-z]{3,30}");

    @Resource(name = "ccInterestEventSink")
    private InterestEventSink interestEventSink;

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;

    public void setInterestEventSink(final InterestEventSink s)
    {
        this.interestEventSink = s;
    }

    public void setConfigurationService(final CcConfigurationService c)
    {
        this.configurationService = c;
    }

    public void maybeRecord(final TurnState state, final Decision decision)
    {
        if (!configurationService.isEnabled("CI-04") || !configurationService.getBoolean("privacy.interestEvents.enabled", true)
                || "NONE".equals(decision.eventSuggestion()))
        {
            return;
        }
        final EventType type = EventType.valueOf(decision.eventSuggestion());
        if (type == EventType.REQUESTED_NOT_FOUND)
        {
            if (!decision.keywords().isEmpty())
            {
                final String token = decision.keywords().get(0).toLowerCase(Locale.ROOT);
                if (TOKEN_OK.matcher(token).matches()) // letters only: no digits, emails or codes can be stored
                {
                    interestEventSink.write(state.customerId, type, token, state.pack);
                }
            }
            return;
        }
        final java.util.Set<String> codes = new java.util.LinkedHashSet<>(decision.codes());
        codes.addAll(state.request.shortlistCodes());
        for (final String code : codes)
        {
            if (state.provenance.contains(code))
            {
                interestEventSink.write(state.customerId, type, code, state.pack);
            }
        }
    }
}

package com.conversational.commerce.core.engine.orchestrator;

/** Deterministic script-based detection so translation does not depend on the model. ASSUMPTION: Hindi (Devanagari) first (N5). */
public class LanguageDetector
{
    public String detect(final String text, final String uiLocale)
    {
        for (int i = 0; i < text.length(); i++)
        {
            final Character.UnicodeBlock block = Character.UnicodeBlock.of(text.charAt(i));
            if (block == Character.UnicodeBlock.DEVANAGARI)
            {
                return "hi";
            }
        }
        return "en";
    }
}

