import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

/**
 * Everything one turn needs. The customer comes from the security context via the facade; tools read it from here and
 * never accept a customer, user or price argument from the model.
 */
public class TurnState
{
    public final String customerId;
    public final String pack;
    public final LocalDate today;
    public final String responseId;
    public final TurnRequest request;
    public final ChatEventListener listener;
    public final TokenMap tokens = new TokenMap();
    /** Product codes, order codes and FAQ ids returned by tools this turn (provenance, D26). */
    public final Set<String> provenance = ConcurrentHashMap.newKeySet();
    /** Values that must never leave in a model payload: formatted prices, margins, uid, email. */
    public final Set<String> secrets = ConcurrentHashMap.newKeySet();
    public final List<TraceStep> trace = Collections.synchronizedList(new ArrayList<>());
    /** The message in English after the translate-in step; used by deterministic parsers. */
    public volatile String workingMessage;
    public volatile String language = "en";
    public final AtomicInteger tokensIn = new AtomicInteger();
    public final AtomicInteger tokensOut = new AtomicInteger();

    private final AtomicInteger steps = new AtomicInteger();
    private final AtomicInteger toolCalls = new AtomicInteger();
    private final int maxSteps;
    private final long deadlineMs;

    public TurnState(final TurnRequest request, final String pack, final LocalDate today, final String responseId,
            final ChatEventListener listener, final int maxSteps, final int maxSeconds)
    {
        this.request = request;
        this.customerId = request.customerId();
        this.pack = pack;
        this.today = today;
        this.responseId = responseId;
        this.listener = listener;
        this.maxSteps = maxSteps;
        this.deadlineMs = System.currentTimeMillis() + maxSeconds * 1000L;
        this.workingMessage = request.message();
        this.secrets.add(request.customerId());
    }

    /** Tool executions are bounded separately from visible steps, so a parallel group is one step but still capped. */
    public void checkToolCall()
    {
        if (toolCalls.incrementAndGet() > maxSteps * 3)
        {
            throw new LimitExceededException("max_tool_calls");
        }
        if (System.currentTimeMillis() > deadlineMs)
        {
            throw new LimitExceededException("max_seconds");
        }
    }

    public void checkLimits()
    {
        if (steps.incrementAndGet() > maxSteps)
        {
            throw new LimitExceededException("max_steps");
        }
        if (System.currentTimeMillis() > deadlineMs)
        {
            throw new LimitExceededException("max_seconds");
        }
    }

    /** Runs a visible step: emits step_started and step_completed around the body and enforces the limits. */
    public <T> T step(final String labelKey, final Supplier<T> body)
    {
        checkLimits();
        final String id = "s" + steps.get();
        listener.onEvent(ChatEvent.stepStarted(id, labelKey));
        try
        {
            final T result = body.get();
            listener.onEvent(ChatEvent.stepCompleted(id, labelKey, "ok"));
            return result;
        }
        catch (final RuntimeException e)
        {
            listener.onEvent(ChatEvent.stepCompleted(id, labelKey, "failed"));
            throw e;
        }
    }

    public void addUsage(final int in, final int out)
    {
        tokensIn.addAndGet(in);
        tokensOut.addAndGet(out);
    }
}

package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.gateway.UsageCounterStore;
import jakarta.annotation.Resource;
import java.time.LocalDate;

/** Per-customer usage caps (PL-06). Runs before the decision call; over the cap means no model call. */
public class UsageCapService
{
    @Resource(name = "ccUsageCounterStore")
    private UsageCounterStore usageCounterStore;

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;

    public void setUsageCounterStore(final UsageCounterStore s)
    {
        this.usageCounterStore = s;
    }

    public void setConfigurationService(final CcConfigurationService c)
    {
        this.configurationService = c;
    }

    /** @return true if the turn may proceed (and counts it), false if the customer is over the cap. */
    public boolean checkAndIncrement(final String customerId, final LocalDate today)
    {
        if (!configurationService.isEnabled("PL-06"))
        {
            return true;
        }
        final String period = periodKey(today);
        final long[] current = usageCounterStore.get(customerId, period);
        final int messageCap = configurationService.getInt("usage.cap.messages", 200);
        final int tokenCap = configurationService.getInt("usage.cap.tokens", 200_000);
        if (current[0] >= messageCap || current[1] >= tokenCap)
        {
            return false;
        }
        usageCounterStore.add(customerId, period, 1, 0);
        return true;
    }

    public void recordTokens(final String customerId, final LocalDate today, final int tokens)
    {
        usageCounterStore.add(customerId, periodKey(today), 0, tokens);
    }

    private String periodKey(final LocalDate today)
    {
        return "MONTH".equalsIgnoreCase(configurationService.getString("usage.cap.period", "DAY")) ? today.toString().substring(0, 7)
                : today.toString();
    }
}

package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.WelcomeItem;
import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.TurnRequest;
import com.conversational.commerce.core.engine.model.ChatEventListener;
import com.conversational.commerce.core.engine.rules.PatternChangeRule;
import com.conversational.commerce.core.engine.rules.ReplenishmentRule;
import jakarta.annotation.Resource;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * Proactive welcome panel (RI-03, SC-05). Template text only: no model call and no cache (N3 is pending owner approval).
 * Deterministic tools only, so the panel is fast and cannot hallucinate.
 */
public class WelcomeService
{
    @Resource(name = "ccToolRegistry")
    private ToolRegistry toolRegistry;

    @Resource(name = "ccHydrator")
    private Hydrator hydrator;

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;

    public void setToolRegistry(final ToolRegistry r)
    {
        this.toolRegistry = r;
    }

    public void setHydrator(final Hydrator h)
    {
        this.hydrator = h;
    }

    public void setConfigurationService(final CcConfigurationService c)
    {
        this.configurationService = c;
    }

    @SuppressWarnings("unchecked")
    public Block build(final String customerId, final LocalDate today)
    {
        if (!configurationService.isEnabled("RI-03"))
        {
            return Block.welcome("welcome", List.of());
        }
        final TurnRequest request = new TurnRequest(customerId, "", null, "en", List.of(), List.of(), List.of());
        final TurnState state = new TurnState(request, configurationService.activePack(), today, UUID.randomUUID().toString(),
                ChatEventListener.NOOP, 8, 9);
        final List<WelcomeItem> items = new ArrayList<>();
        try
        {
            if (configurationService.isEnabled("RI-01"))
            {
                final List<ReplenishmentRule.Item> due = toolRegistry
                        .execute(state, "getReplenishmentRecommendations", Map.of("netPending", true)).as();
                for (final ReplenishmentRule.Item item : due.stream().limit(3).toList())
                {
                    final Map<String, String> params = new LinkedHashMap<>();
                    params.put("code", item.code());
                    params.put("name", hydrator.name(state, item.code()));
                    params.put("quantity", String.valueOf(item.suggestedQuantity()));
                    params.put("estimate", "true");
                    items.add(new WelcomeItem(item.overdue() ? "overdue" : "due", "welcome.due", params));
                }
            }
            if (configurationService.isEnabled("RI-02"))
            {
                final List<Order> pending = toolRegistry.execute(state, "getPendingOrders", Map.of()).as();
                if (!pending.isEmpty())
                {
                    items.add(new WelcomeItem("pending", "welcome.pending", Map.of("count", String.valueOf(pending.size()))));
                }
            }
            if (configurationService.isEnabled("RI-04"))
            {
                final List<PatternChangeRule.Observation> changes = toolRegistry
                        .execute(state, "detectPurchasePatternChanges", Map.of()).as();
                for (final PatternChangeRule.Observation o : changes.stream().limit(2).toList())
                {
                    final Map<String, String> params = new LinkedHashMap<>();
                    params.put("code", o.code());
                    params.put("name", hydrator.name(state, o.code()));
                    params.put("percent", String.valueOf(o.changePercent()));
                    params.put("direction", o.direction().name());
                    params.put("earlierAverage", String.format("%.0f", o.earlierAverage()));
                    params.put("recentAverage", String.format("%.0f", o.recentAverage()));
                    items.add(new WelcomeItem("patternChange", "welcome.patternChange", params));
                }
            }
        }
        catch (final RuntimeException e)
        {
            // A failed tool must not break the page: show what we have.
        }
        return Block.welcome("welcome", items);
    }
}

package com.conversational.commerce.core.engine.orchestrator;

