package com.conversational.commerce.core.engine.orchestrator;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.Comparison;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import java.util.List;
import java.util.Map;

/**
 * SPI (PL-08): an ordered graph of deterministic steps for one intent. The model may choose only the intent; the steps,
 * limits and parallel groups are fixed in Java.
 */
public interface WorkflowTemplate
{
    /** @param blocks blocks without the final text; @param templateKey fixed text key; @param facts text facts for COMPOSE;
     *  @param slots backend-formatted figures; @param table non-null selects the EXPLAIN task and the table check */
    record Output(List<Block> blocks, String templateKey, Map<String, Object> facts, Map<String, String> slots, Comparison table,
            List<String> suggestedActions, String interestCode)
    {
        public static Output of(final List<Block> blocks, final String templateKey, final Map<String, Object> facts,
                final Map<String, String> slots)
        {
            return new Output(blocks, templateKey, facts, slots, null, List.of(), null);
        }
    }

    Intent intent();

    Output run(TurnState state, Decision decision);
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.orchestrator.Hydrator;
import com.conversational.commerce.core.engine.orchestrator.ToolRegistry;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.orchestrator.WorkflowTemplate;
import jakarta.annotation.Resource;
import java.util.Map;

public abstract class AbstractWorkflow implements WorkflowTemplate
{
    @Resource(name = "ccToolRegistry")
    protected ToolRegistry toolRegistry;

    @Resource(name = "ccHydrator")
    protected Hydrator hydrator;

    @Resource(name = "ccConfigurationService")
    protected CcConfigurationService configurationService;

    public void setToolRegistry(final ToolRegistry r)
    {
        this.toolRegistry = r;
    }

    public void setHydrator(final Hydrator h)
    {
        this.hydrator = h;
    }

    public void setConfigurationService(final CcConfigurationService c)
    {
        this.configurationService = c;
    }

    protected ToolResult tool(final TurnState state, final String labelKey, final String name, final Map<String, Object> args)
    {
        return state.step(labelKey, () -> toolRegistry.execute(state, name, args));
    }

    protected int parallelTimeoutSeconds()
    {
        return configurationService.getInt("orchestration.maxSeconds", 9);
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.Recommendation;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.rules.BasketReviewRule.Flag;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** BASKET_REVIEW (SC-08): the list comes from the validated request body (A11), never from server state. */
public class BasketReviewWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.BASKET_REVIEW;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        if (state.request.purchaseList().isEmpty())
        {
            return Output.of(List.of(), "basket_empty", Map.of(), Map.of());
        }
        final ToolResult result = tool(state, "step.reviewingYourList", "reviewPurchaseList", Map.of());
        final List<Flag> flags = result.as();
        final List<Recommendation> items = flags.stream()
                .map(f -> hydrator.recommendation(state, f.code(), 0, f.type().name(), f.type() == com.conversational.commerce.core.engine.rules.BasketReviewRule.FlagType.FORGOTTEN_USUAL))
                .toList();
        final Map<String, String> slots = new LinkedHashMap<>();
        slots.put("flagCount", String.valueOf(flags.size()));
        return new Output(List.of(Block.recommendations("b-flags", items, false)), "basket_review", Map.of("flags", flags.size()),
                slots, null, List.of(), null);
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.ListLine;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.MoneyFormat;
import com.conversational.commerce.core.engine.orchestrator.ToolRegistry.Call;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.rules.BudgetPlanner;
import com.conversational.commerce.core.engine.rules.ReplenishmentRule;
import com.conversational.commerce.core.engine.tools.PurchaseHistoryTool;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** BUDGET_PLAN (SC-04): usual items from history, due items first, fitted into the budget in integer arithmetic. */
public class BudgetPlanWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.BUDGET_PLAN;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        if (decision.budgetAmount() == null)
        {
            return Output.of(List.of(), "budget_clarify", Map.of(), Map.of());
        }
        final List<ToolResult> group = state.step("step.checkingHistory", () -> toolRegistry.executeParallel(state,
                List.of(new Call("getCustomerPurchaseHistory", Map.of("windowDays", 365)),
                        new Call("getReplenishmentRecommendations", Map.of())),
                parallelTimeoutSeconds()));
        final List<PurchaseHistoryTool.Entry> history = group.get(0).as();
        final List<ReplenishmentRule.Item> due = group.get(1).as();
        final Set<String> dueCodes = new HashSet<>();
        due.forEach(d -> dueCodes.add(d.code()));
        final List<Map<String, Object>> usual = new ArrayList<>();
        for (final PurchaseHistoryTool.Entry e : history)
        {
            final Map<String, Object> m = new LinkedHashMap<>();
            m.put("code", e.code());
            m.put("quantity", Math.max(1, e.totalQuantity() / Math.max(1, e.orderCount())));
            m.put("score", e.orderCount() * 10 + (dueCodes.contains(e.code()) ? 100 : 0));
            usual.add(m);
        }
        final long budgetMinor = MoneyFormat.toMinor(decision.budgetAmount());
        final ToolResult planResult = tool(state, "step.fittingBudget", "planBudgetPurchase",
                Map.of("budgetMinor", budgetMinor, "usualItems", usual));
        final BudgetPlanner.Plan plan = planResult.as();
        final List<ListLine> lines = new ArrayList<>();
        for (final BudgetPlanner.Line l : plan.lines())
        {
            lines.add(hydrator.line(state, l.code(), l.quantity(), "budget plan", l.reduced() ? "Quantity reduced to fit" : null));
        }
        final Map<String, String> slots = new LinkedHashMap<>();
        slots.put("budget", hydrator.format(state, plan.budgetMinor()));
        slots.put("total", hydrator.format(state, plan.totalMinor()));
        slots.put("excludedCount", String.valueOf(plan.excluded().size()));
        final List<Block> blocks = new ArrayList<>(List.of(Block.purchaseList("b-plan", lines)));
        return new Output(blocks, "budget_plan", Map.of("lines", lines.size()), slots, null, List.of("ADD_ALL_TO_LIST"), null);
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.Comparison;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.Product;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** COMPARE (SC-07): products from the message, the browser shortlist (re-validated by the catalogue) or a search; table first. */
public class CompareWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.COMPARE;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        final Set<String> codes = new LinkedHashSet<>(decision.codes());
        codes.addAll(state.request.shortlistCodes());
        if (codes.size() < 2 && !decision.keywords().isEmpty())
        {
            final ToolResult search = tool(state, "step.searchingCatalogue", "searchProducts",
                    Map.of("keywords", decision.keywords(), "limit", 3));
            final List<Product> found = search.as();
            found.forEach(p -> codes.add(p.code()));
        }
        if (codes.size() < 2)
        {
            return Output.of(List.of(Block.clarification("b-clarify", "Which products should I compare?", List.of())), "clarify",
                    Map.of(), Map.of());
        }
        final List<String> limited = new ArrayList<>(codes).subList(0, Math.min(4, codes.size()));
        final ToolResult result = tool(state, "step.comparingAttributes", "getComparisonAttributes", Map.of("codes", limited));
        final Comparison table = result.as();
        return new Output(List.of(Block.comparison("b-compare", table)), "compare", Map.of("attributes", table.rows().size()),
                Map.of(), table, List.of(), limited.get(0));
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.Faq;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.RelevanceJudge;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import jakarta.annotation.Resource;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** FAQ (KN-01, D16): lexical shortlist, model picks ids, the answer is the approved text, never model prose. */
public class FaqWorkflow extends AbstractWorkflow
{
    @Resource(name = "ccRelevanceJudge")
    private RelevanceJudge relevanceJudge;

    public void setRelevanceJudge(final RelevanceJudge j)
    {
        this.relevanceJudge = j;
    }

    @Override
    public Intent intent()
    {
        return Intent.FAQ;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        final ToolResult shortlist = tool(state, "step.searchingApprovedAnswers", "getFaqAnswer",
                Map.of("keywords", decision.keywords()));
        final List<Faq> candidates = shortlist.as();
        if (candidates.isEmpty())
        {
            return Output.of(List.of(), "faq_none", Map.of(), Map.of());
        }
        final Map<String, String> idToQuestion = new LinkedHashMap<>();
        candidates.forEach(f -> idToQuestion.put(f.id(), f.question()));
        final List<String> chosen = state.step("step.pickingAnswer",
                () -> relevanceJudge.judgeFaq(state, String.join(" ", decision.keywords()), idToQuestion));
        if (chosen.isEmpty())
        {
            return Output.of(List.of(), "faq_none", Map.of(), Map.of());
        }
        final ToolResult answers = tool(state, "step.readingApprovedAnswer", "getFaqAnswer", Map.of("entryIds", chosen.subList(0, 1)));
        final List<Faq> faqs = answers.as();
        return Output.of(List.of(Block.text("b-faq", faqs.get(0).answer())), null, Map.of(), Map.of());
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.ProductCard;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.Product;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.MoneyFormat;
import com.conversational.commerce.core.engine.orchestrator.RelevanceJudge;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import jakarta.annotation.Resource;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** FIND_PRODUCT (SC-02): search, optional budget filter in Java, relevance judge, hydrate. */
public class FindProductWorkflow extends AbstractWorkflow
{
    @Resource(name = "ccRelevanceJudge")
    private RelevanceJudge relevanceJudge;

    public void setRelevanceJudge(final RelevanceJudge j)
    {
        this.relevanceJudge = j;
    }

    @Override
    public Intent intent()
    {
        return Intent.FIND_PRODUCT;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        if (decision.keywords().isEmpty() && decision.categoryHint().isBlank())
        {
            return Output.of(List.of(Block.clarification("b-clarify", "What will you use it for?",
                    List.of("Surface or material", "Size or quantity", "Budget per unit"))), "clarify", Map.of(), Map.of());
        }
        final Map<String, Object> args = new LinkedHashMap<>();
        args.put("keywords", decision.keywords());
        args.put("filters", decision.filters());
        args.put("limit", 20);
        final ToolResult search = tool(state, "step.searchingCatalogue", "searchProducts", args);
        List<Product> candidates = search.as();
        if (decision.maxUnitAmount() != null && !candidates.isEmpty())
        {
            final ToolResult eligible = tool(state, "step.applyingPriceLimit", "getBudgetEligibleProducts",
                    Map.of("candidateCodes", candidates.stream().map(Product::code).toList(), "maxUnitMinor",
                            MoneyFormat.toMinor(decision.maxUnitAmount())));
            final List<String> ok = eligible.as();
            candidates = candidates.stream().filter(p -> ok.contains(p.code())).toList();
        }
        if (candidates.isEmpty())
        {
            return new Output(List.of(), "find_none", Map.of(), Map.of(), null, List.of(), null);
        }
        final List<Product> toJudge = candidates;
        final List<String> constraints = new ArrayList<>(decision.filters().entrySet().stream().map(e -> e.getKey() + "=" + e.getValue()).toList());
        final List<RelevanceJudge.Pick> picks = state.step("step.judgingFit",
                () -> relevanceJudge.judge(state, String.join(" ", decision.keywords()), constraints, toJudge));
        final List<ProductCard> cards = new ArrayList<>();
        for (final RelevanceJudge.Pick pick : picks)
        {
            final Map<String, String> reasons = new LinkedHashMap<>();
            reasons.put("fit", pick.fit());
            pick.matchedAttributes().forEach(a -> reasons.put("matches:" + a, "yes"));
            cards.add(hydrator.card(state, pick.code(), reasons));
        }
        if (cards.isEmpty())
        {
            return new Output(List.of(), "find_none", Map.of(), Map.of(), null, List.of(), null);
        }
        return new Output(List.of(Block.productCards("b-products", cards)), "find_product", Map.of("count", cards.size()),
                Map.of("count", String.valueOf(cards.size())), null, List.of("ADD_TO_LIST"), cards.get(0).code());
    }
}

