package com.conversational.commerce.core.engine.provider;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import de.hybris.platform.servicelayer.exceptions.SystemException;
import jakarta.annotation.Resource;
import java.io.IOException;
import java.util.Map;
import org.apache.commons.lang3.StringUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

/**
 * Shared HTTP handling. Errors follow the owner's convention: non-200 logs the status only (the body may echo user
 * content) and throws SystemException; null content throws SystemException; InterruptedException restores the flag.
 */
public abstract class AbstractHttpAdapter implements ModelProviderAdapter
{
    private static final Logger LOG = LogManager.getLogger(AbstractHttpAdapter.class);
    protected static final ObjectMapper MAPPER = new ObjectMapper();
    private static final String TIMEOUT_KEY = "cc.http.requestTimeoutMs";
    private static final String CONNECT_TIMEOUT_KEY = "cc.http.connectTimeoutMs";

    @Resource(name = "ccConfigurationService")
    protected CcConfigurationService configurationService;

    private HttpTransport transport;

    public void setConfigurationService(final CcConfigurationService configurationService)
    {
        this.configurationService = configurationService;
    }

    public void setTransport(final HttpTransport transport)
    {
        this.transport = transport;
    }

    @Override
    public String tier()
    {
        return configurationService.getString("cc.provider." + providerCode() + ".tier", "paid");
    }

    @Override
    public boolean isAvailable()
    {
        return StringUtils.isNotBlank(baseUrl()) && StringUtils.isNotBlank(apiKey())
                && configurationService.getBoolean("cc.provider." + providerCode() + ".enabled", true);
    }

    protected String baseUrl()
    {
        return configurationService.getString("cc.provider." + providerCode() + ".baseUrl", "");
    }

    /** Keys are read by alias and never logged. ASSUMPTION: alias defaults to the provider code. */
    protected String apiKey()
    {
        final String alias = configurationService.getString("cc.provider." + providerCode() + ".keyAlias", providerCode());
        return configurationService.getString("cc.provider.key." + alias, "");
    }

    protected abstract String endpoint(String model);

    protected abstract Map<String, String> headers();

    protected abstract String buildBody(String model, ModelRequest request) throws JsonProcessingException;

    protected abstract JsonNode extractContent(JsonNode response);

    protected abstract int[] extractUsage(JsonNode response);

    @Override
    public ModelResult call(final String model, final ModelRequest request)
    {
        final long start = System.currentTimeMillis();
        try
        {
            final String body = buildBody(model, request);
            final HttpTransport.Response response = getTransport().post(baseUrl() + endpoint(model), headers(), body,
                    configurationService.getInt(TIMEOUT_KEY, 8000));
            if (response.status() != 200)
            {
                LOG.warn("Model provider {} returned status {}", providerCode(), response.status()); // status only
                throw new SystemException("Model provider returned status " + response.status());
            }
            final JsonNode root = MAPPER.readTree(response.body());
            final JsonNode content = root == null ? null : extractContent(root);
            if (content == null || content.isNull() || content.isMissingNode())
            {
                throw new SystemException("Model provider returned no content");
            }
            final int[] usage = extractUsage(root);
            return new ModelResult(content, usage[0], usage[1], providerCode(), model, System.currentTimeMillis() - start);
        }
        catch (final InterruptedException e)
        {
            Thread.currentThread().interrupt();
            throw new SystemException("Model call interrupted", e);
        }
        catch (final IOException e)
        {
            // ASSUMPTION: remaining catch blocks were truncated in the owner's screenshot (docs/assumptions.md AS-06).
            LOG.warn("Model provider {} call failed: {}", providerCode(), e.getClass().getSimpleName());
            throw new SystemException("Model provider call failed", e);
        }
    }

    private HttpTransport getTransport()
    {
        if (transport == null)
        {
            transport = new JdkHttpTransport(configurationService.getInt(CONNECT_TIMEOUT_KEY, 3000));
        }
        return transport;
    }

    /** Parses model text as JSON; a non-JSON answer is a schema failure the router may retry. */
    protected JsonNode parseJsonText(final String text)
    {
        try
        {
            return MAPPER.readTree(text);
        }
        catch (final JsonProcessingException e)
        {
            return null;
        }
    }

    protected static ObjectNode object()
    {
        return MAPPER.createObjectNode();
    }
}

package com.conversational.commerce.core.engine.provider;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.Map;

/**
 * UNVERIFIED request shape (docs/verification-log.md): forced tool use with the schema as input_schema.
 * Never route ZDR clients to Fable or Mythos models (E07): the model comes from route.&lt;task&gt;.model, not from code.
 */
public class AnthropicAdapter extends AbstractHttpAdapter
{
    @Override
    public String providerCode()
    {
        return "anthropic";
    }

    @Override
    protected String endpoint(final String model)
    {
        return "/v1/messages";
    }

    @Override
    protected Map<String, String> headers()
    {
        return Map.of("Content-Type", "application/json", "x-api-key", apiKey(), "anthropic-version", "2023-06-01");
    }

    @Override
    protected String buildBody(final String model, final ModelRequest request) throws JsonProcessingException
    {
        final ObjectNode root = object();
        root.put("model", model);
        root.put("max_tokens", request.maxOutputTokens());
        root.put("temperature", request.temperature());
        root.put("system", request.systemPrompt());
        root.putArray("messages").addObject().put("role", "user").put("content", request.payload().json());
        final String toolName = request.promptId().replaceAll("[^A-Za-z0-9_-]", "_");
        final ObjectNode tool = root.putArray("tools").addObject();
        tool.put("name", toolName);
        tool.put("description", "Return the structured answer.");
        tool.set("input_schema", MAPPER.readTree(request.schemaJson()));
        root.putObject("tool_choice").put("type", "tool").put("name", toolName);
        return MAPPER.writeValueAsString(root);
    }

    @Override
    protected JsonNode extractContent(final JsonNode response)
    {
        for (final JsonNode block : response.path("content"))
        {
            if ("tool_use".equals(block.path("type").asText()))
            {
                return block.path("input");
            }
        }
        return null;
    }

    @Override
    protected int[] extractUsage(final JsonNode response)
    {
        return new int[] { response.path("usage").path("input_tokens").asInt(0),
                response.path("usage").path("output_tokens").asInt(0) };
    }
}

package com.conversational.commerce.core.engine.provider;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import jakarta.annotation.Resource;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.lang3.StringUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class DefaultModelRouter implements ModelRouter
{
    private static final Logger LOG = LogManager.getLogger(DefaultModelRouter.class);

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;

    @Resource(name = "ccModelAdapters")
    private List<ModelProviderAdapter> adapters;

    public void setConfigurationService(final CcConfigurationService configurationService)
    {
        this.configurationService = configurationService;
    }

    public void setAdapters(final List<ModelProviderAdapter> adapters)
    {
        this.adapters = adapters;
    }

    @Override
    public ModelResult call(final ModelRequest request)
    {
        final String prefix = "route." + request.task().name().toLowerCase() + ".";
        final List<String[]> chain = new ArrayList<>();
        final String provider = configurationService.getString(prefix + "provider", "");
        if (StringUtils.isNotBlank(provider))
        {
            chain.add(new String[] { provider, configurationService.getString(prefix + "model", "") });
        }
        for (final String entry : configurationService.getString(prefix + "fallback", "").split(","))
        {
            final String[] parts = entry.trim().split(":", 2);
            if (parts.length == 2 && StringUtils.isNotBlank(parts[0]))
            {
                chain.add(new String[] { parts[0].trim(), parts[1].trim() });
            }
        }
        for (final String[] step : chain)
        {
            final ModelProviderAdapter adapter = find(step[0]);
            if (adapter == null || !adapter.isAvailable())
            {
                continue;
            }
            if ("free".equalsIgnoreCase(adapter.tier()) && !configurationService.syntheticDataOnly())
            {
                LOG.warn("Provider {} skipped: free tier is refused outside synthetic-data sites", adapter.providerCode());
                continue;
            }
            try
            {
                final ModelResult result = adapter.call(step[1], request);
                if (result.json() != null && !result.json().isMissingNode())
                {
                    return result;
                }
            }
            catch (final RuntimeException e)
            {
                LOG.warn("Provider {} failed for task {}: {}", adapter.providerCode(), request.task(), e.getClass().getSimpleName());
            }
        }
        throw new ModelUnavailableException("no provider available for task " + request.task());
    }

    private ModelProviderAdapter find(final String code)
    {
        for (final ModelProviderAdapter adapter : adapters)
        {
            if (adapter.providerCode().equalsIgnoreCase(code))
            {
                return adapter;
            }
        }
        return null;
    }
}

