import com.conversational.commerce.core.engine.gateway.BusinessAttributeGateway;
import com.conversational.commerce.core.engine.model.Domain.BusinessAttribute;
import jakarta.annotation.Resource;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/**
 * Business recommendation controls (CI-03, D24). The only reader of margin and priority. It returns an order of codes
 * and nothing else, so margin cannot reach a model, a response or a log.
 */
public class BusinessRanker
{
    @Resource(name = "ccBusinessAttributeGateway")
    private BusinessAttributeGateway businessAttributeGateway;

    public void setBusinessAttributeGateway(final BusinessAttributeGateway gateway)
    {
        this.businessAttributeGateway = gateway;
    }

    public List<String> rank(final List<String> codes)
    {
        final List<String> ordered = new ArrayList<>(codes);
        ordered.sort(Comparator.comparingLong((String c) -> -score(c))); // stable: ties keep the incoming order
        return ordered;
    }

    private long score(final String code)
    {
        final Optional<BusinessAttribute> attribute = businessAttributeGateway.attributeOf(code);
        return attribute.map(a -> a.priority() * 1_000_000_000L + a.marginMinor()).orElse(0L);
    }
}

package com.conversational.commerce.core.engine.rules;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Function;

/** Cross-sell and bundle suggestions from aggregated co-purchase counts (CI-01, CI-02). Deterministic. */
public class CoPurchaseRule
{
    public record Suggestion(String code, int supportCount)
    {
    }

    public List<Suggestion> complements(final Collection<String> basket, final Function<String, Map<String, Integer>> pairCounts,
            final int minSupport, final int limit)
    {
        final Set<String> inBasket = Set.copyOf(basket);
        final Map<String, Integer> totals = new TreeMap<>();
        for (final String code : basket)
        {
            for (final Map.Entry<String, Integer> e : pairCounts.apply(code).entrySet())
            {
                if (!inBasket.contains(e.getKey()))
                {
                    totals.merge(e.getKey(), e.getValue(), Integer::sum);
                }
            }
        }
        final List<Suggestion> result = new ArrayList<>();
        totals.forEach((code, count) ->
        {
            if (count >= minSupport)
            {
                result.add(new Suggestion(code, count));
            }
        });
        result.sort(Comparator.comparingInt((Suggestion s) -> -s.supportCount()).thenComparing(Suggestion::code));
        return result.size() > limit ? new ArrayList<>(result.subList(0, limit)) : result;
    }
}

package com.conversational.commerce.core.engine.rules;

import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Domain.OrderLine;
import com.conversational.commerce.core.engine.model.Domain.OrderStatus;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Purchase-pattern change detection (D12): recent order quantities against the earlier average. */
public class PatternChangeRule
{
    public enum Direction
    {
        DOWN, UP
    }

    public record Observation(String code, double earlierAverage, double recentAverage, int changePercent,
            Direction direction, int earlierSample, int recentSample)
    {
    }

    public List<Observation> detect(final List<Order> orders, final int thresholdPct, final int minSample,
            final int recentOrders)
    {
        final List<Order> sortedOrders = new ArrayList<>(orders);
        sortedOrders.removeIf(o -> o.status() == OrderStatus.CANCELLED);
        sortedOrders.sort(Comparator.comparing(Order::placedOn));
        final Map<String, List<Integer>> series = new TreeMap<>();
        for (final Order order : sortedOrders)
        {
            for (final OrderLine line : order.lines())
            {
                series.computeIfAbsent(line.productCode(), k -> new ArrayList<>()).add(line.quantity());
            }
        }
        final List<Observation> result = new ArrayList<>();
        for (final Map.Entry<String, List<Integer>> entry : series.entrySet())
        {
            final List<Integer> q = entry.getValue();
            if (recentOrders < 1 || q.size() < minSample + recentOrders)
            {
                continue;
            }
            final List<Integer> recent = q.subList(q.size() - recentOrders, q.size());
            final List<Integer> earlier = q.subList(0, q.size() - recentOrders);
            final double earlierAvg = earlier.stream().mapToInt(Integer::intValue).average().orElse(0);
            final double recentAvg = recent.stream().mapToInt(Integer::intValue).average().orElse(0);
            if (earlierAvg <= 0)
            {
                continue;
            }
            final int change = (int) Math.round(Math.abs(recentAvg - earlierAvg) / earlierAvg * 100);
            if (change >= thresholdPct)
            {
                result.add(new Observation(entry.getKey(), earlierAvg, recentAvg, change,
                        recentAvg < earlierAvg ? Direction.DOWN : Direction.UP, earlier.size(), recent.size()));
            }
        }
        result.sort(Comparator.comparingInt((Observation o) -> -o.changePercent()).thenComparing(Observation::code));
        return result;
    }
}

package com.conversational.commerce.core.engine.rules;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Deterministic grammar for typed or pasted quick-order text (PA-03). Residual text is resolved by catalogue search. */
public class QuickOrderParser
{
    public enum Kind
    {
        CODE, DESCRIPTION, REPLACEMENT_OF
    }

    public record RawLine(String rawText, Kind kind, String codeHint, String description, Integer quantity)
    {
    }

    private static final Pattern CODE = Pattern.compile("\\b([A-Z]{2,4}-\\d{3,6})\\b");
    private static final Pattern QTY_FIRST = Pattern.compile("^(\\d{1,6})\\s*(?:x|×|of|units? of|pcs? of)?\\s+(.+)$",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern QTY_AFTER = Pattern.compile("^(.+?)\\s*(?:x|×)\\s*(\\d{1,6})$", Pattern.CASE_INSENSITIVE);
    private static final Pattern REPLACES = Pattern.compile("(?:replaces?|replacement (?:for|of)|substitute (?:for|of))\\s+"
            + "([A-Z]{2,4}-\\d{3,6})", Pattern.CASE_INSENSITIVE);
    private static final Pattern FILLER = Pattern.compile("^(?:need|i need|please add|add|order|want|and|also)\\s+",
            Pattern.CASE_INSENSITIVE);

    public List<RawLine> parse(final String text)
    {
        final List<RawLine> lines = new ArrayList<>();
        if (text == null)
        {
            return lines;
        }
        for (final String part : text.split("(?i)[\\n;,]+|\\s+and\\s+(?=\\d|whatever)"))
        {
            final String trimmed = part.trim().replaceAll("[.]+$", "");
            final String once = FILLER.matcher(trimmed).replaceFirst("").trim();
            final String segment = FILLER.matcher(once).replaceFirst("").trim();
            if (segment.isEmpty())
            {
                continue;
            }
            lines.add(parseSegment(segment));
        }
        return lines;
    }

    private RawLine parseSegment(final String segment)
    {
        final Matcher replaces = REPLACES.matcher(segment);
        if (replaces.find())
        {
            final Matcher qty = Pattern.compile("^(\\d{1,6})\\b").matcher(segment);
            return new RawLine(segment, Kind.REPLACEMENT_OF, replaces.group(1).toUpperCase(), null,
                    qty.find() ? Integer.valueOf(qty.group(1)) : null);
        }
        Integer quantity = null;
        String rest = segment;
        final Matcher first = QTY_FIRST.matcher(segment);
        final Matcher after = QTY_AFTER.matcher(segment);
        if (first.matches())
        {
            quantity = Integer.valueOf(first.group(1));
            rest = first.group(2).trim();
        }
        else if (after.matches())
        {
            quantity = Integer.valueOf(after.group(2));
            rest = after.group(1).trim();
        }
        final Matcher code = CODE.matcher(rest);
        if (code.find())
        {
            return new RawLine(segment, Kind.CODE, code.group(1), null, quantity);
        }
        return new RawLine(segment, Kind.DESCRIPTION, null, rest, quantity);
    }
}

package com.conversational.commerce.core.engine.rules;

import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Domain.OrderLine;
import com.conversational.commerce.core.engine.model.Domain.OrderStatus;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Simple rule-based replenishment (D11): average interval between the customer's own orders. */
public class ReplenishmentRule
{
    // FUTURE SCOPE: unit-level replenishment (D34): feed orders of the whole B2B unit instead of one customer.

    public record Item(String code, int suggestedQuantity, int intervalDays, int daysSinceLast, boolean overdue,
            boolean estimate)
    {
    }

    public List<Item> compute(final List<Order> orders, final LocalDate today, final int windowDays, final int minOrders,
            final double dueRatio)
    {
        final LocalDate from = today.minusDays(windowDays);
        final Map<String, TreeMap<LocalDate, Integer>> byProduct = new TreeMap<>();
        for (final Order order : orders)
        {
            if (order.status() == OrderStatus.CANCELLED || order.placedOn().isBefore(from) || order.placedOn().isAfter(today))
            {
                continue;
            }
            for (final OrderLine line : order.lines())
            {
                byProduct.computeIfAbsent(line.productCode(), k -> new TreeMap<>()).merge(order.placedOn(), line.quantity(),
                        Integer::sum);
            }
        }
        final List<Item> result = new ArrayList<>();
        for (final Map.Entry<String, TreeMap<LocalDate, Integer>> entry : byProduct.entrySet())
        {
            final TreeMap<LocalDate, Integer> dates = entry.getValue();
            if (dates.size() < Math.max(2, minOrders))
            {
                continue;
            }
            final List<LocalDate> sorted = new ArrayList<>(dates.keySet());
            long gapSum = 0;
            for (int i = 1; i < sorted.size(); i++)
            {
                gapSum += ChronoUnit.DAYS.between(sorted.get(i - 1), sorted.get(i));
            }
            final int interval = (int) Math.max(1, Math.round((double) gapSum / (sorted.size() - 1)));
            final int since = (int) ChronoUnit.DAYS.between(sorted.get(sorted.size() - 1), today);
            final double ratio = (double) since / interval;
            if (ratio < dueRatio)
            {
                continue;
            }
            final int avgQty = (int) Math.max(1, Math.round(dates.values().stream().mapToInt(Integer::intValue).average().orElse(1)));
            result.add(new Item(entry.getKey(), avgQty, interval, since, ratio > 1.0, true));
        }
        result.sort(Comparator.comparingInt((Item i) -> i.overdue() ? 0 : 1).thenComparing(Item::code));
        return result;
    }

    /** Removes or reduces suggestions already covered by pending orders (RI-02). */
    public List<Item> netAgainstPending(final List<Item> items, final List<Order> pendingOrders)
    {
        final Map<String, Integer> pendingQty = new TreeMap<>();
        for (final Order order : pendingOrders)
        {
            for (final OrderLine line : order.lines())
            {
                pendingQty.merge(line.productCode(), line.quantity(), Integer::sum);
            }
        }
        final List<Item> result = new ArrayList<>();
        for (final Item item : items)
        {
            final int pending = pendingQty.getOrDefault(item.code(), 0);
            final int remaining = item.suggestedQuantity() - pending;
            if (remaining > 0)
            {
                result.add(new Item(item.code(), remaining, item.intervalDays(), item.daysSinceLast(), item.overdue(), true));
            }
        }
        return result;
    }
}

package com.conversational.commerce.core.engine.sanitiser;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.conversational.commerce.core.engine.provider.ModelTask;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.Resource;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class DefaultSanitiser implements Sanitiser
{
    public static class SanitiserDisabledException extends RuntimeException
    {
        public SanitiserDisabledException()
        {
            super("sanitiser disabled: external model calls fail closed");
        }
    }

    private static final ObjectMapper MAPPER = new ObjectMapper();

    @Resource(name = "ccConfigurationService")
    private CcConfigurationService configurationService;

    @Resource(name = "ccSanitisationRules")
    private List<SanitisationRule> rules;

    private final FieldPolicy fieldPolicy = new FieldPolicy();
    private final EgressPolicy egressPolicy = new EgressPolicy();
    private final OutboundGuard outboundGuard = new OutboundGuard();

    public void setConfigurationService(final CcConfigurationService configurationService)
    {
        this.configurationService = configurationService;
    }

    public void setRules(final List<SanitisationRule> rules)
    {
        this.rules = rules;
    }

    @Override
    public SanitisedPayload sanitise(final ModelTask task, final Map<String, Object> fields, final TokenMap tokens,
            final Collection<String> forbiddenValues)
    {
        if (!configurationService.isEnabled("PL-03") || !configurationService.getBoolean("cc.sanitiser.enabled", true))
        {
            throw new SanitiserDisabledException();
        }
        final Set<String> allowed = egressPolicy.allowedFields(task);
        final Map<String, Object> out = new LinkedHashMap<>();
        final List<String> dropped = new ArrayList<>();
        for (final Map.Entry<String, Object> e : fields.entrySet())
        {
            if (!allowed.contains(e.getKey()) || fieldPolicy.classify(e.getKey()) == FieldPolicy.Class_.NEVER)
            {
                dropped.add(e.getKey());
                continue;
            }
            out.put(e.getKey(), mask(e.getValue(), tokens));
        }
        final String json;
        try
        {
            json = MAPPER.writeValueAsString(out);
        }
        catch (final JsonProcessingException e)
        {
            throw new IllegalStateException("payload could not be serialised", e);
        }
        outboundGuard.check(json, forbiddenValues);
        return new SanitisedPayload(json, dropped);
    }

    private Object mask(final Object value, final TokenMap tokens)
    {
        if (value instanceof String text)
        {
            String masked = text;
            for (final SanitisationRule rule : rules)
            {
                masked = rule.apply(masked, tokens);
            }
            return masked;
        }
        if (value instanceof Collection<?> collection)
        {
            final List<Object> list = new ArrayList<>();
            collection.forEach(v -> list.add(mask(v, tokens)));
            return list;
        }
        if (value instanceof Map<?, ?> map)
        {
            final Map<String, Object> copy = new LinkedHashMap<>();
            for (final Map.Entry<?, ?> e : map.entrySet())
            {
                final String key = String.valueOf(e.getKey());
                if (fieldPolicy.classify(key) != FieldPolicy.Class_.NEVER)
                {
                    copy.put(key, mask(e.getValue(), tokens));
                }
            }
            return copy;
        }
        return value;
    }
}

