package com.conversational.commerce.core.engine.sanitiser;

import java.util.Locale;
import java.util.Set;

/** Classifies outbound field names (PL-03). NEVER fields are dropped and audited, whatever a task allows. */
public class FieldPolicy
{
    public enum Class_
    {
        ALLOW, TOKENISE, NEVER
    }

    private static final Set<String> NEVER_FRAGMENTS = Set.of("price", "total", "margin", "priority", "customername", "email",
            "phone", "address", "pk", "customer", "uid", "supplier", "amount", "cost");
    private static final Set<String> TOKENISE_FIELDS = Set.of("orderCode", "orderCodes", "dealerRef");

    public Class_ classify(final String fieldName)
    {
        final String lower = fieldName.toLowerCase(Locale.ROOT);
        for (final String fragment : NEVER_FRAGMENTS)
        {
            if (lower.contains(fragment))
            {
                return Class_.NEVER;
            }
        }
        return TOKENISE_FIELDS.contains(fieldName) ? Class_.TOKENISE : Class_.ALLOW;
    }
}

package com.conversational.commerce.core.engine.sanitiser;

import java.util.Collection;
import java.util.Locale;

/** Last check before any external call: no value the backend marked as secret may appear in the final payload. */
public class OutboundGuard
{
    public static class EgressBlockedException extends RuntimeException
    {
        public EgressBlockedException(final String message)
        {
            super(message);
        }
    }

    /** @param forbiddenValues prices returned in this turn, margin values, customer uid and email. Never logged. */
    public void check(final String finalJson, final Collection<String> forbiddenValues)
    {
        final String haystack = finalJson.toLowerCase(Locale.ROOT);
        for (final String forbidden : forbiddenValues)
        {
            if (forbidden != null && forbidden.length() >= 3 && haystack.contains(forbidden.toLowerCase(Locale.ROOT)))
            {
                throw new EgressBlockedException("egress_blocked"); // value deliberately not in the message
            }
        }
    }
}

package com.conversational.commerce.core.engine.sanitiser;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Regex masking rule producing typed placeholders such as [EMAIL_1]. */
public class RegexMaskingRule implements SanitisationRule
{
    public static final RegexMaskingRule EMAIL = new RegexMaskingRule("EMAIL",
            Pattern.compile("[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}"));
    public static final RegexMaskingRule ORDER_CODE = new RegexMaskingRule("ORDER",
            Pattern.compile("\\b(?:ORD|PO)[-#]?\\d{4,}\\b|\\b\\d{8}\\b"));
    public static final RegexMaskingRule PHONE = new RegexMaskingRule("PHONE",
            Pattern.compile("(?<![\\w-])\\+?\\d[\\d\\s-]{8,}\\d(?![\\w-])"));
    public static final RegexMaskingRule LONG_DIGITS = new RegexMaskingRule("NUM", Pattern.compile("\\b\\d{9,}\\b"));

    private final String type;
    private final Pattern pattern;

    public RegexMaskingRule(final String type, final Pattern pattern)
    {
        this.type = type;
        this.pattern = pattern;
    }

    @Override
    public String apply(final String text, final TokenMap tokens)
    {
        final Matcher matcher = pattern.matcher(text);
        final StringBuilder out = new StringBuilder();
        while (matcher.find())
        {
            matcher.appendReplacement(out, Matcher.quoteReplacement(tokens.register(type, matcher.group())));
        }
        matcher.appendTail(out);
        return out.toString();
    }
}

